=== RUST HARNESS ===
//! Rust port of `tests/test11.cpp`: run all eleven `idna` entry points over
//! every input and print the results on one space-separated line each.
//!
//! Inputs come from the command line; with no arguments the C++ driver falls
//! back to a fixed trio, and so does this one.

#[path = "src/idna/mod.rs"]
mod idna;

use std::env;
use std::ffi::OsString;
use std::io::{self, Write};

fn main() {
    let mut inputs: Vec<Vec<u8>> = Vec::new();

    // `argc > 1` in the original: every argument after the program name.
    for arg in env::args_os().skip(1) {
        inputs.push(arg_bytes(arg));
    }

    if inputs.is_empty() {
        inputs = vec![
            b"one".to_vec(),
            b"two.three".to_vec(),
            b"four.five.six".to_vec(),
        ];
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    // 调用11个不同的API
    for input in &inputs {
        let mut line: Vec<u8> = Vec::new();
        push_field(&mut line, &idna::to_ascii(input));
        push_field(&mut line, &idna::to_unicode(input));
        push_field(&mut line, &idna::punycode_encode(input));
        push_field(&mut line, &idna::punycode_decode(input));
        push_field(&mut line, bool_field(idna::is_valid_domain(input)));
        push_field(&mut line, bool_field(idna::is_valid_label(input)));
        push_field(&mut line, bool_field(idna::is_ascii_domain(input)));
        push_field(&mut line, bool_field(idna::is_idn_domain(input)));
        push_field(&mut line, &idna::to_lower(input));
        push_field(&mut line, &idna::normalize(input));
        line.extend_from_slice(idna::count_labels(input).to_string().as_bytes());
        line.push(b'\n');

        if out.write_all(&line).is_err() {
            return;
        }
    }

    let _ = out.flush();
}

/// Appends one value plus the trailing space that `<< value << " "` emits.
fn push_field(line: &mut Vec<u8>, value: &[u8]) {
    line.extend_from_slice(value);
    line.push(b' ');
}

/// `std::cout << bool` prints `1`/`0` unless `boolalpha` is set, and it isn't.
fn bool_field(value: bool) -> &'static [u8] {
    if value {
        b"1"
    } else {
        b"0"
    }
}

/// Arguments reach `main` as raw bytes in C++, so take them as raw bytes here
/// too rather than requiring valid UTF-8.
#[cfg(unix)]
fn arg_bytes(arg: OsString) -> Vec<u8> {
    use std::os::unix::ffi::OsStringExt;
    arg.into_vec()
}

#[cfg(not(unix))]
fn arg_bytes(arg: OsString) -> Vec<u8> {
    arg.to_string_lossy().into_owned().into_bytes()
}

//! Domain and label predicates.

use super::{MAX_DOMAIN_LENGTH, MAX_LABEL_LENGTH};

/// Mirrors `idna::is_valid_domain()`: `!s.empty() && s.length() <= 255`.
///
/// The bound is a byte count, so a 86-code-point CJK domain (258 bytes) is
/// rejected even though it is well under 255 characters.
pub fn is_valid_domain(input: &[u8]) -> bool {
    !input.is_empty() && input.len() <= MAX_DOMAIN_LENGTH
}

/// Mirrors `idna::is_valid_label()`: `!s.empty() && s.length() <= 63`.
///
/// Note the C++ routine checks the whole string, not each dot-separated label,
/// and applies no character rules at all.
pub fn is_valid_label(input: &[u8]) -> bool {
    !input.is_empty() && input.len() <= MAX_LABEL_LENGTH
}

/// Mirrors `idna::is_ascii_domain()`: every byte must be non-negative when read
/// as a `char`, i.e. `< 0x80`. An empty string is vacuously ASCII.
pub fn is_ascii_domain(input: &[u8]) -> bool {
    input.iter().all(|&b| b < 0x80)
}

/// Mirrors `idna::is_idn_domain()`: `!is_ascii_domain(s)`.
pub fn is_idn_domain(input: &[u8]) -> bool {
    !is_ascii_domain(input)
}
=== MOD ===
//! Byte-faithful re-implementation of the `idna` C++ helper library.
//!
//! The C++ library threads everything through `std::string`, which is a plain
//! byte container. Nothing in it decodes UTF-8, so a faithful port has to work
//! on bytes too: `length()` counts bytes, `substr` slices at byte offsets, and
//! `::tolower` in the "C" locale only touches `A`..=`Z`. Working on `&[u8]`
//! rather than `&str` keeps that behaviour exact and also lets the driver
//! handle arguments that are not valid UTF-8.

// The library mirrors the C++ surface; the test11 driver only exercises part of it.
#![allow(dead_code)]

pub mod convert;
pub mod labels;
pub mod transform;
pub mod validate;

pub use convert::{punycode_decode, punycode_encode, to_ascii, to_unicode};
pub use labels::count_labels;
pub use transform::{normalize, to_lower};
pub use validate::{is_ascii_domain, is_idn_domain, is_valid_domain, is_valid_label};

/// ASCII Compatible Encoding prefix that marks a punycode-encoded label.
pub const ACE_PREFIX: &[u8] = b"xn--";

/// Longest label the validator accepts, in bytes.
pub const MAX_LABEL_LENGTH: usize = 63;

/// Shortest label the validator accepts, in bytes.
pub const MIN_LABEL_LENGTH: usize = 1;

/// Longest domain the validator accepts, in bytes.
pub const MAX_DOMAIN_LENGTH: usize = 255;

/// Separator between labels.
pub const LABEL_SEPARATOR: u8 = b'.';

/// Mirrors `idna::get_max_label_length()`.
pub fn get_max_label_length() -> i32 {
    MAX_LABEL_LENGTH as i32
}

/// Mirrors `idna::get_min_label_length()`.
pub fn get_min_label_length() -> i32 {
    MIN_LABEL_LENGTH as i32
}
=== LABELS ===
//! Label counting.

use super::LABEL_SEPARATOR;

/// Mirrors `idna::count_labels()`: one more than the number of `.` bytes.
///
/// Empty labels are counted, so `""` is 1, `"."` is 2 and `"a..b"` is 3. The
/// C++ counter is an `int`, which is what the return type reflects.
pub fn count_labels(input: &[u8]) -> i32 {
    let dots = input.iter().filter(|&&b| b == LABEL_SEPARATOR).count();
    dots as i32 + 1
}

