#!/usr/bin/perl
use strict; use warnings;
my $C="/workspace/dataset/test11_executable"; my $R="/output/test11";
our $PROBES=0; our @DIV=();

sub runbin {
    my ($bin,@args)=@_;
    my $pid=open(my $fh, "-|");
    die "fork" unless defined $pid;
    if ($pid==0) { open(STDERR,'>','/dev/null'); exec($bin,@args) or exit 127; }
    local $/; my $out=<$fh>; $out='' unless defined $out;
    close($fh); my $code=$?>>8;
    return ($out,$code);
}
# extract field5 for the FIRST input only, given arg bytes
sub f5_of {
    my ($out,$arg)=@_;
    my $k = ($arg =~ tr/ //) + 1;
    my @toks = split(/ /, $out, -1);
    return defined($toks[4*$k]) ? $toks[4*$k] : '?';
}
sub check1 {
    my ($arg,$label)=@_;
    $PROBES++;
    my ($co,$cc)=runbin($C,$arg);
    my ($ro,$rc)=runbin($R,$arg);
    my $ok = ($co eq $ro && $cc==$rc);
    unless($ok){
      push @DIV,[$label,$arg,$co,$ro,$cc,$rc];
      print "DIVERGE [$label] arglen=".length($arg)."\n";
      print "  arg(hex)=".unpack("H*",substr($arg,0,120))."\n";
      print "  C(".$cc.")=".unpack("H*",substr($co,0,300))."\n";
      print "  R(".$rc.")=".unpack("H*",substr($ro,0,300))."\n";
    }
    return (f5_of($co,$arg), $ok);
}
sub checkmulti {
    my ($label,@args)=@_;
    $PROBES += scalar(@args);
    my ($co,$cc)=runbin($C,@args);
    my ($ro,$rc)=runbin($R,@args);
